// Checks for the intent "Show prices in the reader's currency".
import { test, expect } from "../harness/test.js";
import * as products from "../src/products.js";
import worker from "../src/index.js";

async function home(query = "") {
  const res = await worker.fetch(new Request("http://shop.test/" + query));
  return res.text();
}

test("formatPrice keeps US dollars as the default", () => {
  expect(products.formatPrice(1999)).toBe("$19.99");
  expect(products.formatPrice(1999, "USD")).toBe("$19.99");
});

test("formatPrice converts to euros at 0.92, to the cent", () => {
  expect(products.formatPrice(1999, "EUR")).toBe("€18.39");
  expect(products.formatPrice(1450, "EUR")).toBe("€13.34");
  expect(products.formatPrice(999, "EUR")).toBe("€9.19");
});

test("formatPrice converts to rupees at 83, in whole rupees with a comma for thousands", () => {
  expect(products.formatPrice(1999, "INR")).toBe("₹1,659");
  expect(products.formatPrice(2400, "INR")).toBe("₹1,992");
  expect(products.formatPrice(999, "INR")).toBe("₹829");
});

test("formatPrice falls back to US dollars for an unknown currency", () => {
  expect(products.formatPrice(1999, "XYZ")).toBe("$19.99");
});

test("?currency=EUR shows every price in euros", async () => {
  const html = await home("?currency=EUR");
  expect(html).toContain("€18.39");
  expect(html).toContain("€9.19");
  expect(html).not.toMatch(/\$\d/);
});

test("?currency=INR shows every price in rupees", async () => {
  const html = await home("?currency=INR");
  expect(html).toContain("₹1,659");
  expect(html).not.toMatch(/\$\d/);
});

test("the page shows US dollars when there is no ?currency", async () => {
  expect(await home()).toContain("$19.99");
});

test("the page has links to switch the currency", async () => {
  const html = await home();
  expect(html).toMatch(/href="[^"]*currency=EUR/);
  expect(html).toMatch(/href="[^"]*currency=INR/);
});

// Checks for the intent "Add a dark mode".
import { test, expect } from "../harness/test.js";
import { CSS } from "../src/styles.js";
import worker from "../src/index.js";

async function home() {
  const res = await worker.fetch(new Request("http://shop.test/"));
  return res.text();
}

function headerOf(html) {
  const match = html.match(/<header[\s\S]*?<\/header>/);
  return match ? match[0] : "";
}

function toggleOf(html) {
  const match = headerOf(html).match(/<button[^>]*theme-toggle[^>]*>/);
  return match ? match[0] : "";
}

function darkBlock() {
  const match = CSS.match(/\[data-theme=["']?dark["']?\][^{]*\{([^}]*)\}/);
  return match ? match[1] : "";
}

test("the header has a theme toggle button", async () => {
  expect(toggleOf(await home())).toMatch(/class="[^"]*\btheme-toggle\b/);
});

test("the toggle reports its state with aria-pressed", async () => {
  expect(toggleOf(await home())).toMatch(/aria-pressed="(true|false)"/);
});

test("an inline script switches data-theme and aria-pressed", async () => {
  const scripts = (await home()).match(/<script\b[^>]*>[\s\S]*?<\/script>/g) || [];
  const code = scripts.join("\n");
  expect(code).toMatch(/data-theme|dataset\.theme/);
  expect(code).toContain("aria-pressed");
});

test("the styles set dark colour tokens under [data-theme=\"dark\"]", () => {
  expect(darkBlock()).toMatch(/--bg\s*:/);
  expect(darkBlock()).toMatch(/--ink\s*:/);
});

test("the styles follow prefers-color-scheme: dark", () => {
  expect(CSS).toMatch(/prefers-color-scheme:\s*dark/);
});

test("colours still come from CSS custom properties", () => {
  expect(CSS).toMatch(/background:\s*var\(--bg\)/);
  expect(CSS).toMatch(/color:\s*var\(--ink\)/);
});

// Checks for the intent "Search books by title or author".
import { test, expect } from "../harness/test.js";
import * as products from "../src/products.js";
import worker from "../src/index.js";

function find(query) {
  if (typeof products.findProducts !== "function") throw new Error("src/products.js must export findProducts(query)");
  return products.findProducts(query);
}

function ids(books) {
  return books.map((book) => book.id);
}

async function home(query = "") {
  const res = await worker.fetch(new Request("http://shop.test/" + query));
  return res.text();
}

function headerOf(html) {
  const match = html.match(/<header[\s\S]*?<\/header>/);
  return match ? match[0] : "";
}

test("findProducts matches titles, in any case", () => {
  expect(ids(find("TIDEWATER"))).toEqual([1]);
  expect(ids(find("tide"))).toEqual([1, 8]);
});

test("findProducts matches authors", () => {
  expect(ids(find("quill"))).toEqual([1]);
  expect(ids(find("Moss"))).toEqual([8]);
});

test("findProducts trims the query", () => {
  expect(ids(find("  marram  "))).toEqual([6]);
});

test("an empty or missing query returns every book", () => {
  expect(find("").length).toBe(products.PRODUCTS.length);
  expect(find(undefined).length).toBe(products.PRODUCTS.length);
});

test("the header has a search form with a q field", async () => {
  const header = headerOf(await home());
  expect(header).toMatch(/<form\b[^>]*role="search"/);
  expect(header).toMatch(/<input\b[^>]*name="q"/);
});

test("?q= filters the list and keeps the prices", async () => {
  const html = await home("?q=tide");
  expect(html).toContain("The Tidewater Almanac");
  expect(html).toContain("A Small Book of Tides");
  expect(html).not.toContain("Knots for Small Boats");
  expect(html).toContain("$19.99");
  expect(html).toContain("$9.99");
});

test("the search box keeps the query", async () => {
  expect(await home("?q=marram")).toMatch(/<input\b[^>]*value="marram"/);
});

test("a search with no match says so", async () => {
  const html = await home("?q=zzzz");
  expect(html).toContain("No books match your search.");
  for (const book of products.PRODUCTS) expect(html).not.toContain(book.title);
});

test("the page escapes the query", async () => {
  const html = await home("?q=" + encodeURIComponent('<script>"x"'));
  expect(html).not.toContain('<script>"x"');
});

// Checks for the intent "Mark staff picks".
import { test, expect } from "../harness/test.js";
import { PRODUCTS } from "../src/products.js";
import worker from "../src/index.js";

const PICKS = [1, 6, 8];

async function items() {
  const res = await worker.fetch(new Request("http://shop.test/"));
  const html = await res.text();
  return html.match(/<li\b[^>]*class="[^"]*\bbook\b[^"]*"[^>]*>[\s\S]*?<\/li>/g) || [];
}

function itemFor(list, id) {
  const book = PRODUCTS.find((b) => b.id === id);
  return list.find((item) => item.includes(book.title)) || "";
}

function priceLine(item) {
  const match = item.match(/<p\b[^>]*class="[^"]*\bprice\b[^"]*"[^>]*>[\s\S]*?<\/p>/);
  return match ? match[0] : "";
}

test("exactly three books are staff picks: ids 1, 6 and 8", () => {
  expect(PRODUCTS.filter((book) => book.staffPick).map((book) => book.id)).toEqual(PICKS);
});

test("every book has a staffPick boolean", () => {
  for (const book of PRODUCTS) expect(typeof book.staffPick).toBe("boolean");
});

test("each staff pick shows a Staff pick badge in its price line", async () => {
  const list = await items();
  for (const id of PICKS) {
    expect(priceLine(itemFor(list, id))).toMatch(/<span\b[^>]*class="[^"]*\bbadge\b[^"]*"[^>]*>\s*Staff pick\s*<\/span>/);
  }
});

test("other books show no badge", async () => {
  const list = await items();
  for (const book of PRODUCTS.filter((b) => !PICKS.includes(b.id))) {
    expect(itemFor(list, book.id)).not.toContain("Staff pick");
  }
});

test("the price stays in the price line", async () => {
  const list = await items();
  expect(priceLine(itemFor(list, 1))).toContain("$19.99");
});

// Checks for the intent "Add a JSON endpoint for one book".
import { test, expect } from "../harness/test.js";
import { PRODUCTS } from "../src/products.js";
import worker from "../src/index.js";

async function get(path) {
  const res = await worker.fetch(new Request("http://shop.test" + path));
  const type = res.headers.get("content-type") || "";
  const body = type.includes("application/json") ? await res.json() : await res.text();
  return { status: res.status, type, body };
}

test("GET /api/products/3 returns that book as JSON", async () => {
  const res = await get("/api/products/3");
  expect(res.status).toBe(200);
  expect(res.type).toContain("application/json");
  expect(res.body).toEqual(PRODUCTS.find((book) => book.id === 3));
});

test("every book has its own URL", async () => {
  for (const book of PRODUCTS) {
    const res = await get("/api/products/" + book.id);
    expect(res.status).toBe(200);
    expect(res.body.title).toBe(book.title);
  }
});

test("an unknown id returns 404 with a JSON error", async () => {
  const res = await get("/api/products/999");
  expect(res.status).toBe(404);
  expect(res.type).toContain("application/json");
  expect(typeof res.body.error).toBe("string");
});

test("an id that is not a number returns 404 with a JSON error", async () => {
  const res = await get("/api/products/tidewater");
  expect(res.status).toBe(404);
  expect(typeof res.body.error).toBe("string");
});

test("the list endpoint still returns every book", async () => {
  const res = await get("/api/products");
  expect(res.status).toBe(200);
  expect(res.body.length).toBe(PRODUCTS.length);
});
